/** Institutos del torneo; el resto de equipos son SOLO fichables. */
const BRACKET_TEAMS = new Set(['raimon', 'occult', 'otaku', 'shuriken', 'farm', 'kirkwood', 'royal', 'zeus'])

/** Equipos extra (temporada 2 y Alius): su gente entra por el ojeador. */
export const EXTRA_TEAMS: string[] = [...new Set(PLAYERS.map((p) => p.team))].filter((t) => !BRACKET_TEAMS.has(t))

/** Nombre visible de los equipos extra (no están en `teams.ts`). */
export const TEAM_NAMES: Record<string, string> = {
  kfc: 'Inazuma KFC',
  oumihara: 'Instituto Oumihara',
  mikage: 'Mikage Sennou',
  manyuuji: 'Instituto Manyuuji',
  yokato: 'Instituto Yokato',
  'gemini-storm': 'Tormenta Géminis',
  epsilon: 'Épsilon',
  'diamond-dust': 'Diamond Dust',
  prominence: 'Prominence',
  genesis: 'Génesis',
  chaos: 'Caos',
  windies: 'The Windies',
  'extra-stars': 'Extra Stars',
  'kage-no-hero': 'Kage no Hero',
}

export const PLAYER_BY_ID = new Map(PLAYERS.map((p) => [p.id, p]))

/**
 * Ids que existieron en catálogos anteriores y cambiaron al corregir la
 * identidad del personaje (la wiki resolvía al «Lion»/«Diver» de Orion en
 * vez de a los clásicos). Las partidas guardadas viejas los siguen citando.
 */
const LEGACY_IDS: Record<string, string> = {
  hellion: 'leonard-o-shea',
  'hellion-2': 'leonard-o-shea-2',
  scuba: 'chad-taylor',
}

export function getPlayerBase(id: string): PlayerBase {
  const p = PLAYER_BY_ID.get(id) ?? PLAYER_BY_ID.get(LEGACY_IDS[id] ?? '')
  if (!p) throw new Error(`Jugador desconocido: ${id}`)
  return p
}

/** Jugadores de un instituto concreto. */
export function playersOfTeam(teamId: string): PlayerBase[] {
  return PLAYERS.filter((p) => p.team === teamId)
}

export function squadCounts(teamId: string): { DEF: number; MED: number; DEL: number } {
  const own = playersOfTeam(teamId)
  const n = (pos: PlayerBase['position']) => own.filter((p) => p.position === pos).length
  return { DEF: n('DEF'), MED: n('MED'), DEL: n('DEL') }
}

/** Formación que este instituto puede alinear con su plantilla real. */
export function formationFor(teamId: string): string {
  return bestFormationFor(squadCounts(teamId)).id
}

/**
 * Convocatorias que el CANON deja cortas de 14 (o sin portero). Se completan
 * con jugadores de equipos hermanos — los Alius entre ellos — para que
 * cualquier instituto se pueda jugar con un once y un banquillo de verdad.
 */
const SQUAD_FILL: Record<string, string[]> = {
  kfc: ['alex-hawke'],
  // El crawl coló una técnica y un club como «jugadores» (Shark Shooter y
  // Surf Club): fuera del roster, y estos dos completan la convocatoria.
  oumihara: ['a-woodbridge'],
  'big-waves': ['alain-favreau'],
  // OJO con las academias Alius: nada de prestar a la MISMA persona en sus
  // dos épocas (albert-denver y albert-denver-2 son el mismo chaval) ni de
  // prestarle a un equipo la otra versión de alguien de su propio roster —
  // se veían «jugadores repetidos». `startingSquad` además lo blinda.
  'gemini-storm': ['albert-denver-2', 'anna-mole', 'ashton-malone'],
  epsilon: ['albert-denver-2', 'ashton-malone', 'ben-blowton-2'],
  'diamond-dust': ['ashton-malone', 'ben-blowton-2', 'anna-mole'],
  prominence: ['alan-downhill', 'albert-denver', 'anna-mole'],
  genesis: ['alan-downhill', 'albert-denver', 'anna-mole'],
  'the-empire': ['a-woodbridge'],
  hakuren: ['a-woodbridge'],
  'dark-emperors': ['a-woodbridge', 'alain-favreau', 'alan-coe', 'alan-master-2'],
  'epsilon-kai': ['alex-hawke', 'a-woodbridge', 'alain-favreau', 'alan-coe'],
  'rose-griffon': ['a-woodbridge'],
  ogre: ['a-woodbridge', 'alain-favreau', 'alan-coe'],
  'neo-japan': ['a-woodbridge'],
  nishinomiya: ['adamas-quarell'],
  'toufuu-ikokukan': ['adamas-quarell'],
  mannouzaka: ['abram-cadabra'],
  tengawara: ['abram-cadabra'],
  'gassan-kunimitsu': ['abram-cadabra', 'acme-rapture'],
  'hakuren-go': ['abram-cadabra'],
  'kaiou-gakuen': ['abram-cadabra'],
  seidouzan: ['abram-cadabra'],
  'unlimited-shining': ['abram-cadabra', 'acme-rapture', 'ade-kebe'],
}

/**
 * CONVOCATORIA con la que arranca cada instituto: los 14 de su plantilla
 * real, ordenados con el once de la formación primero y el resto de
 * banquillo. Antes se recortaba a 11 y los otros 3 se quedaban fuera hasta
 * que el ojeador los ofrecía — pero son SUS jugadores, deben salir de casa.
 */
export function startingSquad(teamId: string, formationId?: string): string[] {
  const own = playersOfTeam(teamId)
  const f = getFormation(formationId ?? formationFor(teamId))
  const line = (pos: PlayerBase['position'], n: number) =>
    own.filter((p) => p.position === pos).slice(0, n).map((p) => p.id)
  const picked = [...line('POR', 1), ...line('DEF', f.defs), ...line('MED', f.mids), ...line('DEL', f.fwds)]
  const bench = own.filter((p) => !picked.includes(p.id)).map((p) => p.id)
  const extra = SQUAD_FILL[teamId] ?? []
  // Si el equipo no tiene portero propio, el prestado entra en el ONCE.
  const borrowedKeeper = picked.length && own.some((p) => p.position === 'POR')
    ? []
    : extra.filter((id) => PLAYER_BY_ID.get(id)?.position === 'POR').slice(0, 1)
  // BLINDAJE: un préstamo jamás mete a la MISMA PERSONA dos veces en la
  // convocatoria (albert-denver-2 en el equipo de albert-denver, etc.).
  const persona = (id: string) => id.replace(/-\d+$/, '')
  const enCasa = new Set([...borrowedKeeper, ...picked, ...bench].map(persona))
  const rest = extra.filter((id) => !borrowedKeeper.includes(id) && !enCasa.has(persona(id)))
  const fill = rest.slice(0, Math.max(0, 14 - picked.length - bench.length - borrowedKeeper.length))
  return [...borrowedKeeper, ...picked, ...bench, ...fill]
}

/** Once inicial del Raimon (compatibilidad). */
export const RAIMON_STARTING_XI: string[] = startingSquad('raimon').slice(0, 11)

// ---------------------------------------------------------------------------
// LA CADENA SIEMPRE DE MENOS A MÁS: en la serie se aprende primero la versión
// floja y después la evolución, pero el crawl traía algunas cadenas giradas
// (Joseph King despertaba el Escudo Total antes que el Escudo). Se reordena
// por potencia al cargar, y lo que cada jugador SABE de salida pasa a ser el
// principio de su cadena ordenada (más lo que tuviera de fuera de ella).
import { getTechnique as __getTech } from '@/data/inazuma/techniques'
for (const p of PLAYERS) {
  // EL ATRIBUTO DE PORTERO, calculado al cargar (el bloque generado es de 6
  // stats): el portero hereda su oficio de la defensa que traía tuneada de
  // portero; el jugador de campo llega con paradas de andar por casa.
  if (p.stats.portero === undefined) {
    p.stats.portero = p.position === 'POR'
      ? p.stats.defensa
      : Math.round(p.stats.defensa * 0.3 + p.stats.fisico * 0.2)
  }
  if (!p.signature?.length) continue
  const antes = p.signature
  p.signature = [...antes].sort((a, b) => (__getTech(a)?.power ?? 0) - (__getTech(b)?.power ?? 0))
  const deCadena = p.techniques.filter((t) => antes.includes(t)).length
  const deFuera = p.techniques.filter((t) => !antes.includes(t))
  p.techniques = [...p.signature.slice(0, deCadena), ...deFuera]
}
